package com.codearena.problem;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="problems") public class Problem { @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @Column(name="author_id",nullable=false) public UUID authorId; @Column(nullable=false,length=200) public String title; @Column(nullable=false,unique=true,length=220) public String slug; @Column(nullable=false,columnDefinition="text") public String description; @Column(name="input_format",nullable=false,columnDefinition="text") public String inputFormat=""; @Column(name="output_format",nullable=false,columnDefinition="text") public String outputFormat=""; @Column(name="constraints_text",nullable=false,columnDefinition="text") public String constraints=""; @Column(nullable=false) public String difficulty="EASY"; @Column(name="time_limit_ms",nullable=false) public int timeLimitMs=2000; @Column(name="memory_limit_mb",nullable=false) public int memoryLimitMb=256; @Column(name="maximum_score",nullable=false) public int maximumScore=100; @ElementCollection @CollectionTable(name="problem_supported_languages",joinColumns=@JoinColumn(name="problem_id")) @Column(name="language") public Set<String> supportedLanguages=new HashSet<>(); @ManyToMany(fetch=FetchType.LAZY) @JoinTable(name="problem_tags",joinColumns=@JoinColumn(name="problem_id"),inverseJoinColumns=@JoinColumn(name="tag_id")) @org.hibernate.annotations.Fetch(org.hibernate.annotations.FetchMode.SUBSELECT) public Set<Tag> tags=new HashSet<>(); public boolean published=false; @Version public int version; @Column(name="created_at",nullable=false) public Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) public Instant updatedAt=Instant.now(); @PreUpdate void updated(){updatedAt=Instant.now();} }
